<script setup lang="ts">
import {api} from '@/api';
import {managementGo} from '@/shared/management';
import { computed,ref,watch } from 'vue';import { onLoad,onShow } from '@dcloudio/uni-app';import { useI18n } from 'vue-i18n';import { useMerchantStore } from '@/stores/merchant';import PlanList from './components/PlanList.vue';import CustomerAccountList from './components/CustomerAccountList.vue';import StoredValueRecordList from './components/StoredValueRecordList.vue';
const governance=ref(false),management=ref('');
const {t}=useI18n();const merchant=useMerchantStore();const ready=ref(false);const failed=ref(false);const tab=ref('plans');const planNo=ref('');const child=ref<{refresh:()=>unknown}|null>(null);
const tabs=computed(()=>[{key:'plans',label:t('storedValue.plans'),allowed:merchant.can('pay:sv:plan:read')||merchant.can('pay:sv:plan:manage')||merchant.can('pay:sv:recharge:create')},{key:'customers',label:t('storedValue.customers'),allowed:merchant.can('pay:sv:account:read')||(merchant.can('biz:customer')&&merchant.can('pay:sv:recharge:create'))},{key:'records',label:t('storedValue.records'),allowed:merchant.can('pay:sv:account:read')}].filter(x=>x.allowed));
watch(tabs,items=>{if(!items.some(x=>x.key===tab.value))tab.value=items[0]?.key||'';});
onLoad(q=>{if(q?.tab==='customers')tab.value='customers';planNo.value=q?.planNo||'';});
async function load(){failed.value=false;try{await merchant.ensureScope();await merchant.ensureStores();governance.value=false;management.value='';try{if((await api.mSvGovernanceCapability()).enabled){const context=await api.mManagementContext();const saved=String(uni.getStorageSync('management:'+context.actorKey)||'');const selected=context.spaces.find(x=>x.managementNo===saved)||context.spaces[0];if(selected){management.value=selected.managementNo;governance.value=true;}}}catch{}ready.value=true;if(!tabs.value.some(x=>x.key===tab.value))tab.value=tabs.value[0]?.key||'';void child.value?.refresh();}catch{failed.value=true;ready.value=true;}}
onShow(load);
</script>
<template><sh-scaffold :title-suffix="merchant.multiStore ? merchant.currentStore?.name : ''" title-key="storedValue.title" :pending="!ready" :failed="failed" @retry="load" :denied="ready&&!failed&&!tabs.length"><view v-if="ready&&tabs.length" role="button" class="sh-card sh-row sh-row--between sh-hit" @tap="managementGo('storedValueIssuer',{s:merchant.storeNo,local:'1'})"><text>{{t('issuer.storeScope')}}</text><sh-go/></view><view v-if="governance&&management" class="sh-card sh-row sh-row--between sh-hit" @tap="managementGo('storedValueActivity',{m:management,s:merchant.storeNo})"><text>{{t('svGov.activities')}}</text><sh-go/></view><sh-tabs :items="tabs" :active="tab" @change="tab=$event"/><PlanList v-if="ready&&tab==='plans'" ref="child" :governance="governance"/><CustomerAccountList v-else-if="ready&&tab==='customers'" ref="child" :plan-no="planNo"/><StoredValueRecordList v-else-if="ready&&tab==='records'" ref="child"/></sh-scaffold></template>
